CREATE TABLE IF NOT EXISTS email_provider_registry (id INTEGER PRIMARY KEY, domain VARCHAR(255) NOT NULL UNIQUE, provider_name VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL, disposable VARCHAR(10) NOT NULL DEFAULT 'false', source VARCHAR(255) NOT NULL, list_version VARCHAR(80), updated_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_email_provider_registry_domain ON email_provider_registry(domain);
