CREATE TABLE IF NOT EXISTS contact_risk_assessments (id INTEGER PRIMARY KEY, message_analysis_id INTEGER, email_analysis_id INTEGER, indicator_type VARCHAR(30) NOT NULL, indicator VARCHAR(2048) NOT NULL, score INTEGER NOT NULL, classification VARCHAR(30) NOT NULL, confidence VARCHAR(30) NOT NULL, evidence_json TEXT NOT NULL, checked_at TIMESTAMP, FOREIGN KEY(message_analysis_id) REFERENCES message_analysis_records(id), FOREIGN KEY(email_analysis_id) REFERENCES email_analyses(id));
CREATE INDEX IF NOT EXISTS ix_contact_risk_assessments_message_analysis_id ON contact_risk_assessments(message_analysis_id);
